 # Enrichment problems combine two or more independent geometric relationships.
 z=4+v
 b.n(4,'تشابه با ضلع‌های پارامتری و تناظر',s,f'ضلع‌های مثلث اول به ترتیب x، x+2، x+3 و ضلع‌های متناظر مثلث دوم 2x، 3x{signed_term(4-z)}، 5x{signed_term(6-3*z)} هستند؛ دو مثلث متشابه و همهٔ ضلع‌ها مثبت‌اند؛ x چند است؟',z,'نسبت ضلع‌های نخست دو است؛ دو تناسب دیگر را با همین نسبت حل و کنترل کن.',f'solve(3*x+({4-z})-2*(x+2),x)[0]')
 b.n(4,'زاویه‌خوانی جبری در متساوی‌الساقین',t,f'در مثلث متساوی‌الساقین، هر زاویهٔ قاعده x و زاویهٔ خارجی رأس 4x−{2*a} درجه است؛ x چند است؟',a,'زاویهٔ خارجی رأس مجموع دو زاویهٔ قاعده است؛ رابطهٔ جبری را با این مجموع برابر بگذار.',f'solve(4*x-{2*a}-2*x,x)[0]')
 b.n(4,'زاویهٔ بین دو نیمساز داخلی مثلث',c,f'زاویهٔ A در مثلث ABC برابر {2*a} درجه است؛ نیمسازهای داخلی B و C در I همدیگر را قطع می‌کنند؛ زاویهٔ BIC چند درجه است؟',90+a,'در مثلث BIC، دو زاویهٔ B و C نصف زاویه‌های اصلی‌اند؛ مجموع آن دو را از صدوهشتاد کم کن.',f'180-(180-{2*a})/2')
 b.n(4,'ارتفاع وارد بر وتر با مقایسهٔ دو مساحت',s,f'ضلع‌های قائمهٔ مثلث {3*k} و {4*k} و وتر {5*k} است؛ ارتفاع وارد بر وتر چند است؟',F(12*k,5),'مساحت مثلث را یک بار با دو ضلع قائمه و یک بار با وتر و ارتفاع بنویس و برابر بگذار.',f'({3*k}*{4*k})/({5*k})')
 b.n(4,'میانهٔ وارد بر وتر در مثلث قائم',c,f'در مثلث قائم با ضلع‌های قائمه {3*k} و {4*k}، M وسط وتر است؛ با ویژگی میانهٔ وارد بر وتر، طول پاره‌خط از رأس قائمه تا M چند است؟',F(5*k,2),'اول وتر را با فیثاغورس حساب کن؛ در مثلث قائم، میانهٔ وارد بر وتر نصف وتر است.',f'sqrt(({3*k})**2+({4*k})**2)/2')
 b.n(4,'بازسازی مجموع قطرهای متوازی‌الاضلاع',t,f'قطرهای متوازی‌الاضلاع ABCD در O قطع می‌شوند؛ AB={5*k} و محیط مثلث AOB برابر {12*k} است؛ AC+BD چند است؟',14*k,'از محیط، مجموع دو نیم‌قطر را به دست آور؛ هر قطر دو برابر نیم‌قطر متناظر است.',f'2*({12*k}-{5*k})')
 b.n(4,'طول دو مماس با یک مثلث قائم کمکی',c,f'از P بیرون دایرهٔ مرکز O و شعاع {3*k}، دو مماس PA و PB رسم شده است؛ OP={5*k}؛ مجموع PA+PB چند است؟',8*k,'شعاع بر مماس عمود است؛ یک طول مماس را با فیثاغورس حساب کن و برابری دو مماس را به کار ببر.',f'2*sqrt(({5*k})**2-({3*k})**2)')
 b.n(4,'بازیابی محیط کوچک از اختلاف محیط‌های متشابه',s,f'نسبت طول بزرگ به کوچک 3/2 و اختلاف محیط‌ها {5+v} سانتی‌متر است؛ محیط شکل کوچک چند است؟',2*(5+v),'اگر محیط کوچک را p بگیری، محیط بزرگ سه‌دوم p است؛ اختلافشان نیم p می‌شود.',f'{5+v}/(Rational(3,2)-1)')
 b.essay(2,'برهان زاویه‌های متقابل به رأس',t,'با استفاده از مکمل بودن زاویه‌های مجاور ثابت کن زاویه‌های متقابل به رأس برابرند.','هر دو زاویه با یک زاویهٔ مشترک مجموع صدوهشتاد درجه می‌سازند؛ با کم کردن آن زاویهٔ مشترک، دو زاویه برابر می‌شوند.',['ذکر دو رابطهٔ مکمل.','حذف زاویهٔ مشترک و نتیجه.'])
 b.essay(3,'اثبات میانه بودن نیمساز در متساوی‌الساقین',c,'در ABC، فرض AB=AC و AD نیمساز زاویهٔ A است و D روی BC قرار دارد؛ ثابت کن BD=DC.','AB=AC، زاویهٔ BAD=CAD و AD مشترک است؛ دو مثلث ABD و ACD به حالت ضلع، زاویه، ضلع هم‌نهشت‌اند؛ پس BD=DC.',['فرض و حکم روشن.','سه دادهٔ هم‌نهشتی و نام معیار.','نتیجه از ضلع‌های متناظر.'])
 b.essay(3,'اثبات برابری فاصله‌های نقطهٔ عمودمنصف',c,'M روی عمودمنصف AB است؛ ثابت کن MA=MB.','اگر O وسط AB باشد، AO=BO، MO مشترک و دو زاویهٔ O قائمه‌اند؛ دو مثلث AOM و BOM هم‌نهشت‌اند و MA=MB.',['تعریف وسط و عمود.','معیار ضلع، زاویه، ضلع.','تناظر درست.'])
 b.essay(4,'اثبات برابری مماس‌های یک نقطه',c,'از نقطهٔ P بیرون دایرهٔ مرکز O دو مماس PA و PB رسم شده‌اند؛ PA=PB را ثابت کن.','OA=OB چون شعاع‌اند؛ OP وتر مشترک است و شعاع بر مماس در نقطهٔ تماس عمود است؛ دو مثلث قائم OAP و OBP به وتر و ضلع هم‌نهشت‌اند و PA=PB.',['فرض و حکم.','شعاع و مماس عمود.','برابری شعاع‌ها و وتر مشترک.','معیار و نتیجه.'])
 b.essay(3,'ابطال تشابه مستطیل با مساحت متفاوت',s,'آیا مستطیل‌های 2×5 و 4×7 متشابه‌اند؟ استدلال کن.','خیر؛ نسبت ضلع‌های متناظر 2 و 7/5 است و برابر نیست؛ قائم بودن زاویه‌ها به‌تنهایی برای تشابه چهارضلعی کافی نیست.',['محاسبهٔ دو نسبت متناظر.','بیان نابرابری و نتیجه.'])
 b.essay(4,'اثبات نصف شدن قطرهای متوازی‌الاضلاع',c,'در متوازی‌الاضلاع ABCD، قطرها در O همدیگر را قطع کرده‌اند؛ ثابت کن AO=CO.','AB=CD و AB∥CD؛ دو جفت زاویهٔ متناوب داخلی در مثلث‌های AOB و COD برابرند؛ با زاویه، ضلع، زاویه هم‌نهشتی و سپس AO=CO نتیجه می‌شود.',['خواص اضلاع متوازی‌الاضلاع.','دو زاویهٔ متناظر با استناد به موازی‌ها.','معیار هم‌نهشتی و نتیجه.'])
 for q in b.rows:
  if q['objective'] in ['شباهت زنجیره‌ای','تکمیل تشابه از محیط تا طول','مقیاس مساحت در شکل‌های متشابه','بازیابی نسبت از مساحت','پیوند زاویه خارجی و تناسب داخلی','رد وارون یک گزاره هندسی','تقاطع دو شرط زاویه در متوازی‌الاضلاع','فاصلهٔ متناظر پس از دو تبدیل مقیاس']:
   q['level']=3;q['difficulty']=LEVELS[2]
  if q['objective'] in ['زاویه‌های جبری با مجموع مثلث','اهمیت تناظر ضلع در مثلث قائم','نیمساز زاویهٔ رأس و محاسبهٔ زاویه']:
   q['level']=2;q['difficulty']=LEVELS[1]
 return b.finish()
